insert into public.courses (id, language, dialect, title, description, cefr_level, goal_tag, position, published, school, prerequisite_ids)
values ('bbbb0002-0000-4000-8000-000000000007', 'en', null, 'Cloud & DevOps Foundations', 'A hands-on, vendor-neutral tour of how modern software is built, shipped, and run — the cloud, containers, version control, CI/CD, infrastructure as code, and reliability. Structure informed by the ACM Computing Curricula (Systems) recommendations.', null, 'work', 7, true, 'technology', '{bbbb0002-0000-4000-8000-000000000002}')
on conflict (id) do nothing;

insert into public.lessons (course_id, position, title, kind, body, grammar_notes_md, estimated_minutes)
select 'bbbb0002-0000-4000-8000-000000000007', v.pos, v.title, v.kind, v.body::jsonb, v.notes, v.mins
from (values
  (1, 'Diagnostic: where are you now?', 'quiz', '{"questions":[{"prompt":"\"Cloud computing\" is best described as…","options":["storing files only on USB drives","renting computing resources over a network, on demand, and paying for what you use","a single giant computer owned by one company","software that runs without any servers at all"],"answer":1,"explanation":"The cloud is on-demand access to shared, metered computing resources — see ''What the cloud actually is''."},{"prompt":"Which service model gives you raw virtual machines, storage, and networks to manage yourself?","options":["SaaS","PaaS","IaaS","FaaS"],"answer":2,"explanation":"Infrastructure as a Service hands you the building blocks — see ''What the cloud actually is''."},{"prompt":"Webmail you open in a browser is an example of…","options":["IaaS","PaaS","SaaS","a hypervisor"],"answer":2,"explanation":"Software as a Service: you just use the finished app — see ''What the cloud actually is''."},{"prompt":"A container differs from a virtual machine mainly because it…","options":["needs more memory than a VM","includes its own full operating system","shares the host operating system kernel instead of bundling a whole OS","can only run on Windows"],"answer":2,"explanation":"Containers virtualize the OS and share the kernel — see ''Virtual machines vs containers''."},{"prompt":"Git is a…","options":["programming language","distributed version control system","cloud provider","container registry"],"answer":1,"explanation":"Git tracks changes to files over time — see ''Version control with Git''."},{"prompt":"In \"CI/CD\", the CI stands for…","options":["Cloud Infrastructure","Continuous Integration","Container Isolation","Code Inspection"],"answer":1,"explanation":"Continuous Integration: merge and test small changes often — see ''CI/CD pipelines''."},{"prompt":"Infrastructure as Code means…","options":["writing your app in a low-level language","defining servers and networks in version-controlled config files instead of clicking a console","storing passwords inside your source code","running code only on physical machines"],"answer":1,"explanation":"IaC describes infrastructure declaratively in files you can review and reuse — see ''Infrastructure as code''."},{"prompt":"Which trio best captures the raw signals used to monitor a running system?","options":["mouse, keyboard, screen","metrics, logs, and traces","CPU, RAM, disk only","email, chat, phone"],"answer":1,"explanation":"Observability rests on metrics, logs, and traces — covered in the checkpoints and project."}]}'::jsonb, null, 10),
  (2, 'What the cloud actually is (IaaS, PaaS, SaaS)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Define cloud computing and tell IaaS, PaaS, and SaaS apart by *who manages what*. Warm-up: from the diagnostic, which model hands you a bare virtual machine to configure yourself?"},{"heading":"The idea","text":"The *cloud* is simply someone else''s computers that you rent over a network, on demand, and pay for by usage — no buying servers up front. Its defining traits are *on-demand self-service*, *elasticity* (scale up or down quickly), and *metered billing*. Providers sell it at three levels. *IaaS* (Infrastructure as a Service) gives you raw building blocks — virtual machines, storage, networks — and you manage the operating system and everything above it. *PaaS* (Platform as a Service) gives you a managed runtime where you deploy code and the provider handles the OS, patching, and scaling. *SaaS* (Software as a Service) is a finished application you just log into. A useful frame is the *shared responsibility model*: the provider always secures the physical data center, and the higher your service level, the more of the stack they also manage — but the less you can customize."},{"heading":"Worked example","text":"Suppose a team needs a website with a database. With IaaS they rent a virtual machine, install the web server and database themselves, and patch the OS. With PaaS they push their code to a managed app platform and attach a managed database — no OS to patch. With SaaS they skip building entirely and use an off-the-shelf site builder. Same goal, three very different amounts of work and control."},{"heading":"Your turn","text":"Classify each as IaaS, PaaS, or SaaS: (1) renting a bare virtual server and installing your own database; (2) a spreadsheet app you open in a browser; (3) a managed platform where you deploy code and it auto-scales; (4) object storage buckets you wire into your own app. Answers: (1) IaaS, (2) SaaS, (3) PaaS, (4) IaaS."},{"heading":"Common mistakes & exit ticket","text":"Mistake: thinking \"cloud\" means \"no servers\" — there are always servers, you just don''t own or see them. Mistake: assuming SaaS is always cheapest or best; more managed means less control and possible lock-in. Exit: (a) Which model leaves *you* responsible for OS patching? (b) Name one defining trait of the cloud. Answers: IaaS; on-demand self-service (or elasticity, or metered billing)."}]}'::jsonb, 'IaaS → PaaS → SaaS: the higher you climb, the less you manage and the less you control.', 12),
  (3, 'Virtual machines vs containers (Docker)', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain how a container differs from a virtual machine and read a basic container image definition. Warm-up: which one shares the host''s operating system kernel?"},{"heading":"The idea","text":"A *virtual machine* uses a *hypervisor* to emulate a whole computer, so each VM carries its own full operating system — powerful but heavy (gigabytes, slow to start). A *container* instead packages just your app plus its libraries and shares the host''s OS kernel, isolated by features built into the OS. The result is lightweight, starts in seconds, and runs the same on a laptop or in the cloud — killing the \"but it works on my machine\" problem. *Docker* is the most common tool for building and running containers. You describe an *image* (a read-only template) in a text file; a running copy of that image is a *container*; you push images to a *registry* so others can pull them."},{"heading":"Worked example","text":"A minimal image definition for a small web app looks like this:\n```dockerfile\nFROM python:3.12-slim\nWORKDIR /app\nCOPY requirements.txt .\nRUN pip install --no-cache-dir -r requirements.txt\nCOPY . .\nEXPOSE 8000\nCMD [\"python\", \"app.py\"]\n```\nBuild it once and run it anywhere:\n```bash\ndocker build -t myapp:1.0 .\ndocker run -p 8000:8000 myapp:1.0\n```\nThe `FROM` line reuses an existing base image; each instruction adds a cached layer, so rebuilds are fast."},{"heading":"Your turn","text":"Answer: (1) True or false — every container bundles its own complete operating system. (2) Which is generally faster to start, a VM or a container? (3) In Docker, what do we call the read-only template you run? (4) What does pushing to a *registry* let your teammates do? Answers: (1) false — it shares the host kernel; (2) a container; (3) an image; (4) pull and run the exact same image."},{"heading":"Common mistakes & exit ticket","text":"Mistake: treating containers as \"tiny VMs\" — they have no separate kernel, which is why they are lighter but share the host''s isolation model. Mistake: confusing an image (the template) with a container (a running instance). Exit: (a) A container virtualizes the ___, a VM virtualizes the ___. (b) Which command turns a Dockerfile into an image? Answers: operating system, hardware; `docker build`."}]}'::jsonb, 'A VM virtualizes the hardware; a container virtualizes the operating system.', 13),
  (4, 'Version control with Git', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Describe why teams use version control and walk through a basic Git branch-and-merge workflow. Warm-up: what kind of tool is Git — a language, a cloud, or a version control system?"},{"heading":"The idea","text":"*Version control* records the full history of your files so you can see what changed, when, and by whom — and undo safely. *Git* is *distributed*: every clone holds the entire history, so you can work offline and there is no single point of failure. The core objects are the *repository* (the project and its history), the *commit* (a labeled snapshot of changes), and the *branch* (a movable pointer to a line of commits). A common team pattern is the *feature-branch workflow*: branch off the main line, commit your work, open a *pull request* for review, then *merge* back once it passes checks. This keeps the main branch releasable while people work in parallel."},{"heading":"Worked example","text":"A typical loop for one change:\n```bash\ngit switch -c add-login        # create and move to a feature branch\ngit add .                      # stage your changes\ngit commit -m \"Add login form\" # snapshot them with a message\ngit push -u origin add-login   # publish the branch for review\n```\nAfter review approves the pull request, the branch is merged into `main` and can be deleted. If a change breaks something, `git revert` creates a new commit that undoes it without erasing history."},{"heading":"Your turn","text":"Answer: (1) What Git object is a labeled snapshot of changes? (2) Why can you work offline with Git but not with a purely central system? (3) In the feature-branch workflow, what do you open before merging? (4) Which command creates a new branch and switches to it in one step? Answers: (1) a commit; (2) every clone has the full history locally; (3) a pull request; (4) `git switch -c`."},{"heading":"Common mistakes & exit ticket","text":"Mistake: committing straight to the main branch, so a broken change blocks everyone. Mistake: writing vague commit messages like \"fix stuff\" that no one can interpret later. Exit: (a) What does a branch let a team do? (b) Name a safe way to undo a merged change without rewriting history. Answers: work in parallel on isolated lines of work; `git revert`."}]}'::jsonb, 'A commit is a snapshot; a branch is a parallel line of work you later merge back.', 12),
  (5, 'Checkpoint 1', 'quiz', '{"questions":[{"prompt":"In the shared responsibility model, moving from IaaS toward SaaS means…","options":["you manage more of the stack","the provider manages more of the stack","nobody secures the data center","billing stops being metered"],"answer":1,"explanation":"Higher service levels shift management to the provider."},{"prompt":"Elasticity in the cloud refers to…","options":["permanently fixed capacity","the ability to scale resources up and down on demand","encrypting data at rest","a type of container"],"answer":1,"explanation":"Elasticity is on-demand scaling."},{"prompt":"Compared with a virtual machine, a container is generally…","options":["heavier and slower to start","lighter and faster because it shares the host kernel","unable to run web apps","the same thing with a different name"],"answer":1,"explanation":"Containers skip a full guest OS."},{"prompt":"In Docker, a running instance of an image is called a…","options":["registry","hypervisor","container","commit"],"answer":2,"explanation":"Image = template; container = running instance."},{"prompt":"In Git, a branch is best described as…","options":["a full copy of the remote server","a movable pointer to a line of commits","a way to delete history permanently","a container image"],"answer":1,"explanation":"Branches let teams work in parallel."},{"prompt":"The safest way to undo a change that is already on the main branch is to…","options":["delete the repository","force-push over history","use git revert to add an undo commit","email everyone to stop working"],"answer":2,"explanation":"revert undoes without rewriting shared history."}]}'::jsonb, null, 8),
  (6, 'CI/CD pipelines', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what a CI/CD pipeline automates and read a simple pipeline definition. Warm-up: in \"CI/CD\", what does the CI half stand for?"},{"heading":"The idea","text":"*Continuous Integration (CI)* means every change is merged frequently and automatically built and tested, so problems surface within minutes instead of at the end. *Continuous Delivery (CD)* extends this by automatically preparing every passing build for release, so deploying is a routine, low-drama decision; *Continuous Deployment* goes one step further and releases to production automatically once all checks pass. A *pipeline* is the ordered set of automated *stages* — typically build, test, then deploy — that a change flows through. Each stage acts as a gate: if tests fail, the change stops there and never reaches users. This turns releasing from a risky manual event into a repeatable, reviewable process."},{"heading":"Worked example","text":"A minimal, vendor-neutral pipeline expressed in YAML:\n```yaml\nstages:\n  - build\n  - test\n  - deploy\n\nbuild:\n  stage: build\n  script:\n    - docker build -t myapp:$COMMIT_SHA .\n\ntest:\n  stage: test\n  script:\n    - pytest --maxfail=1\n\ndeploy:\n  stage: deploy\n  script:\n    - ./deploy.sh myapp:$COMMIT_SHA\n  only:\n    - main\n```\nHere a change is built into an image tagged with its commit, the tests must pass, and only changes on `main` are deployed. If `pytest` fails, the deploy stage never runs."},{"heading":"Your turn","text":"Answer: (1) What does CI stand for, and what does it automate? (2) What is the difference between continuous *delivery* and continuous *deployment*? (3) In the example, why does a failing test protect users? (4) Why tag the image with the commit rather than always \"latest\"? Answers: (1) Continuous Integration — automatic build and test of every merged change; (2) delivery keeps the release one manual click away, deployment releases automatically; (3) the deploy stage is gated behind passing tests, so broken code stops in the pipeline; (4) it makes each deployed build traceable and easy to roll back to."},{"heading":"Common mistakes & exit ticket","text":"Mistake: calling any automated deploy \"continuous deployment\" — if a human still approves the release, that''s continuous *delivery*. Mistake: skipping the test stage to \"go faster,\" which just moves failures onto users. Exit: (a) What are the three classic pipeline stages? (b) What happens to a change when a stage''s checks fail? Answers: build, test, deploy; it stops at that stage and does not proceed."}]}'::jsonb, 'CI = integrate and test small changes often; CD = automate the path from a passing build to a running release.', 13),
  (7, 'Infrastructure as code', 'reading', '{"sections":[{"heading":"What you''ll be able to do","text":"Explain what Infrastructure as Code is, why it beats clicking around a console, and what \"declarative\" and \"idempotent\" mean. Warm-up: where does IaC store the definition of your servers and networks?"},{"heading":"The idea","text":"*Infrastructure as Code (IaC)* means describing your servers, networks, and services in text files that live in version control, then letting a tool create or update the real resources to match. Most IaC is *declarative*: you state the *desired end state* (\"two web servers and one database\"), not the click-by-click steps, and the tool computes the difference and applies it. Because the file is the source of truth, infrastructure becomes reviewable, repeatable, and easy to recreate — a whole environment can be rebuilt from the file alone. A key property is *idempotence*: applying the same definition twice leaves you in the same state, so re-running is safe. This replaces fragile, undocumented manual setup (\"click-ops\") with something you can diff, test, and roll back like any other code."},{"heading":"Worked example","text":"A small, vendor-neutral declarative definition:\n```yaml\nresources:\n  web_server:\n    count: 2\n    image: myapp:1.0\n    cpu: 1\n    memory: 512MB\n  database:\n    engine: postgres\n    version: \"16\"\n    storage: 20GB\n```\nRun the tool once and it creates two web servers and a database. Change `count` to 3 and re-run: the tool sees one server is missing and adds *only* that one — it does not rebuild the other two. Run it again with no changes and nothing happens. That predictable, no-surprise behavior is idempotence."},{"heading":"Your turn","text":"Answer: (1) What does \"declarative\" mean for infrastructure? (2) Why is storing IaC files in version control valuable? (3) What does idempotence guarantee when you re-run a definition? (4) In the example, what happens to the existing servers when you raise `count` from 2 to 3? Answers: (1) you state the desired end state, not the individual steps; (2) infrastructure becomes reviewable, repeatable, and recoverable like code; (3) the same input yields the same state, so re-running is safe; (4) they are left untouched — only the one missing server is added."},{"heading":"Common mistakes & exit ticket","text":"Mistake: editing infrastructure by hand after applying IaC, causing *drift* between the file and reality. Mistake: hard-coding secrets into the config files instead of injecting them securely at deploy time. Exit: (a) What is drift? (b) Why is idempotence useful when a run is interrupted and you retry it? Answers: a mismatch between the declared state in code and the actual live infrastructure; retrying is safe because re-applying the same definition converges to the same state without duplicating resources."}]}'::jsonb, 'Declare the desired end state; let the tool figure out the steps to reach it. Re-running should change nothing (idempotence).', 13),
  (8, 'Key terms', 'vocab', '{"items":[{"term":"elasticity","translation":"the cloud''s ability to scale resources up or down quickly, on demand","example":"Elasticity let the shop add servers for a sale, then release them afterward."},{"term":"container","translation":"a lightweight package of an app and its dependencies that shares the host OS kernel","example":"The same container ran unchanged on a laptop and in production."},{"term":"commit","translation":"a labeled snapshot of changes recorded in a version control system","example":"Each commit had a clear message explaining the change."},{"term":"pipeline","translation":"an automated sequence of stages (build, test, deploy) a change flows through","example":"The pipeline blocked the release because a test failed."},{"term":"idempotence","translation":"the property that applying the same operation twice yields the same result","example":"Thanks to idempotence, re-running the deploy changed nothing."},{"term":"observability","translation":"the ability to understand a system''s internal state from its outputs — metrics, logs, and traces","example":"Good observability let the team spot the slow database before users noticed."}]}'::jsonb, null, 8),
  (9, 'Checkpoint 2', 'quiz', '{"questions":[{"prompt":"Continuous Integration primarily automates…","options":["buying servers","building and testing every merged change","writing documentation","deleting old branches"],"answer":1,"explanation":"CI catches problems early by building and testing often."},{"prompt":"If a human still approves each release, you are practicing…","options":["continuous deployment","continuous delivery","no automation at all","infrastructure as code"],"answer":1,"explanation":"Delivery keeps a human gate; deployment removes it."},{"prompt":"A declarative infrastructure definition describes…","options":["the exact click-by-click steps","the desired end state, letting the tool reach it","only the application source code","a single container image"],"answer":1,"explanation":"You state the goal; the tool computes the changes."},{"prompt":"Idempotence means re-applying the same definition…","options":["doubles your resources each time","leaves you in the same state","always fails the second time","requires a new commit"],"answer":1,"explanation":"Same input, same state — safe to re-run."},{"prompt":"The three classic signals of observability are…","options":["mouse, keyboard, screen","metrics, logs, and traces","build, test, deploy","IaaS, PaaS, SaaS"],"answer":1,"explanation":"Metrics, logs, and traces reveal internal state."},{"prompt":"\"Drift\" in infrastructure as code refers to…","options":["a slow network","a mismatch between the declared config and the live infrastructure","a failed Git merge","a container restarting"],"answer":1,"explanation":"Drift is when reality no longer matches the code."}]}'::jsonb, null, 8),
  (10, 'Applied project: design a simple deployment pipeline', 'writing', '{"sections":[{"heading":"The task","text":"On paper, design a deployment pipeline for a small web app that lives in a Git repository and ships as a container. You will not run anything — you will plan the flow rigorously, from a code change to a monitored release, using vendor-neutral concepts (not one provider''s console)."},{"heading":"Milestones","text":"1) Choose a service model (IaaS, PaaS, or SaaS-adjacent) for hosting and justify it in one sentence. 2) Describe the Git workflow: how a change goes from a feature branch through a pull request to `main`. 3) List your pipeline stages in order (e.g. build the container image, run tests, deploy) and state what gates each stage. 4) Write, in a few lines of pseudo-YAML, a build → test → deploy pipeline that only deploys from `main`. 5) Name two things you would monitor after deploy (pick from metrics, logs, traces, error rate, latency) and one alert that would tell you to roll back."},{"heading":"Self-check rubric","text":"✔ Your hosting choice names a service model and a reason. ✔ The Git workflow keeps `main` releasable (work happens on branches, merged via review). ✔ Stages are ordered and each has a clear gate, so a failed test stops the release. ✔ Your pipeline only deploys tagged, tested builds from `main` — never straight from a feature branch. ✔ Your monitoring plan names concrete signals and a rollback trigger. If all five hold, you have designed a safe, repeatable release — the core of DevOps."}]}'::jsonb, null, 15)
) as v(pos, title, kind, body, notes, mins)
where not exists (
  select 1 from public.lessons l
  where l.course_id = 'bbbb0002-0000-4000-8000-000000000007' and l.position = v.pos
);
